    relocations=relocation_symbols(game)
    for site,plt,body,kind in BINDINGS:
        code=game.read(site,5)
        if code[0]!=(0xe8 if kind=='call' else 0xe9) or site+5+struct.unpack_from('<i',code,1)[0]!=plt:raise ValueError('direct binding mismatch')
        stub=game.read(plt,6)
        if stub[:2]!=b'\xff\x25' or relocations.get(plt+6+struct.unpack_from('<i',stub,2)[0])!=body:raise ValueError('PLT binding mismatch')
    dwarf=subprocess.check_output(['gdb','-nx','-batch',str(args.assets/'libGameCore_XP2.so'),'-ex',"ptype /o 'GameCore::Player::Trade'"],text=True)
    if sha(dwarf.encode())!=DWARF_SHA:raise ValueError('DWARF mismatch')
    pin=subprocess.check_output(['git','rev-parse',args.source_commit+'^{commit}'],cwd=ROOT,text=True).strip()
    reports=[]
    with tempfile.TemporaryDirectory(prefix='c6-trade-') as tmp:
        tmp=Path(tmp);source=tmp/'source';source.mkdir()
        archive=subprocess.check_output(['git','archive',pin],cwd=ROOT)
        subprocess.run(['tar','-x','-C',str(source)],input=archive,check=True)
        if (source/'tools/linux/player_trade_audit.py').read_bytes()!=Path(__file__).read_bytes():raise ValueError('driver must be committed with candidate')
        paths=[source/'Cargo.toml',source/'Cargo.lock',source/'crates/c6-core/Cargo.toml',*sorted((source/'crates/c6-core/src').rglob('*.rs')),source/'tools/linux/player_trade_audit.py']
        sources={str(x.relative_to(source)):sha(x.read_bytes())for x in paths}
        subprocess.run(['cargo','build','--offline','--release','-p','c6-core'],cwd=source,check=True)
        harness=HARNESS.replace('MODULE',str(source/'crates/c6-core/src/player_trade.rs'))
        (tmp/'candidate.rs').write_text(harness)
        cmd=['rustc','--edition=2021','-Dwarnings','-O',str(tmp/'candidate.rs'),'--extern','c6_core='+str(source/'target/release/libc6_core.rlib'),'-L','dependency='+str(source/'target/release/deps')]
        subprocess.run(cmd+['-o',str(tmp/'candidate')],check=True)
        subprocess.run(cmd+['--test','-o',str(tmp/'tests')],check=True)
        subprocess.run([str(tmp/'tests')],check=True)
        candidate_sha=sha((tmp/'candidate').read_bytes())
        for identity,trace_name,trace_sha in FIXTURES:
            data=gzip.decompress((args.private_root/'evidence/linux-game-load/canonical'/(identity+'.bin.gz')).read_bytes())
            trace=gzip.decompress((args.private_root/'evidence/linux-save-normalization/checkpoint-203-owners'/trace_name).read_bytes())
            if sha(data)!=identity or sha(trace)!=trace_sha:raise ValueError('fixture identity mismatch')
            cuts=sorted([x for x in map(json.loads,trace.splitlines())if x.get('event')=='owner' and x.get('save')==1 and x.get('owner')=='GameCore::Player::Trade'],key=lambda x:x['start'])
            if len(cuts)!=43:raise ValueError('record count mismatch')
            observations=[];digests=[]
            for cut in cuts:
                payload=data[cut['start']:cut['end']];(tmp/'in').write_bytes(payload)
                words=[int(x)for x in subprocess.check_output([str(tmp/'candidate'),str(tmp/'in'),str(tmp/'out')],text=True).split()]
                if (tmp/'out').read_bytes()!=payload or words[0]!=len(payload):raise ValueError('typed comparison mismatch')
                observations.append(words);digests.append(sha(payload))
            reports.append(dict(stream_sha256=identity,trace_sha256=trace_sha,records=len(cuts),record_bytes=sum(x[0]for x in observations),record_items=sum(x[1]for x in observations),first_observed_range=[cuts[0]['start'],cuts[0]['end']],byte_item_caps=sorted(set(tuple(x)for x in observations)),ordered_record_digests_sha256=sha(json.dumps(digests,separators=(',',':')).encode())))
    report=dict(schema='c6-linux-player-trade-v1',checks_passed=True,gamecore_sha256=GAME_SHA,host_sha256=HOST_SHA,current_version=35,version_address='0x2f68bbc',methods=[dict(address=hex(a),size=n,name=name,sha256=h)for a,n,name,h in METHODS],concrete_bindings=[dict(site=hex(a),plt=hex(b),body=hex(c),kind=k)for a,b,c,k in BINDINGS],dwarf_sha256=DWARF_SHA,candidate_source_commit=pin,candidate_archive_sha256=sha(archive),candidate_sources=sources,candidate_sha256=candidate_sha,harness_sha256=sha(harness.encode()),audit_source_sha256=sha(Path(__file__).read_bytes()),fixtures=reports,source_only_tests=2,exact_native_record_byte_item_caps_checked=True,one_short_native_record_byte_item_caps_rejected=True,native_every_truncation_rejected=True,validation_cuts='Trade owner cuts only; production codec has no offsets or search inputs',allocation_policy='aggregate wire byte and collection item caps; each declared count preflights minimum wire before fallible typed reservation; typed dynamic storage independently bounded by max_items, at most size_of nested entry per charged item plus fixed struct; no aggregate heap cap claim',original_execution=False,private_writes=False,complete_current_trade_wire=True,legacy_versions=False,definition_remapping=False,native_read_fixups=False,native_current_read_calls_initialize=True,native_current_read_calls_reset=True,native_current_read_reset_reproduced=False,native_current_read_callbacks_reproduced=False,full_player=False,world_import=False,gameplay_state=False,actions=False,turns=False,next_player_component='GreatPeoplePoints',unknown_save_bytes_masked=False,recorded_raw_save_load_difference_bytes=89198,attribution_reference_revision='5af389445118bed2bdebf7a8a42b219c8fba5175',reference_role='discovery_only')
